1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const FREE_TYPES = 3;
9	const SCORE_WITHIN_FREE_TYPES = 2;
10	const BONUS_PER_EXTRA_TYPE = 2;
11	
12	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
13	
14	const countTypesSeenBy = (army: Card[], index: number): number =>
15	  new Set(
16	    army.filter((_, other) => other !== index).map((card) => card.monster),
17	  ).size;
18	
19	// The first type beyond the free allowance lifts the score by one, to 3. Every
20	// type after that adds the full bonus, giving the run 3, 5, 7, …
21	const SCORE_AT_FIRST_EXTRA_TYPE = SCORE_WITHIN_FREE_TYPES + 1;
22	
23	const scorePerSphinx = (otherTypes: number): number =>
24	  otherTypes > FREE_TYPES
25	    ? SCORE_AT_FIRST_EXTRA_TYPE +
26	      BONUS_PER_EXTRA_TYPE * (otherTypes - FREE_TYPES - 1)
27	    : SCORE_WITHIN_FREE_TYPES;
28	
29	export const scoreArmy = (army: Card[]): number =>
30	  army.reduce(
31	    (score, card, index) =>
32	      isSphinx(card) ? score + scorePerSphinx(countTypesSeenBy(army, index)) : score,
33	    0,
34	  );
35

